import React from "react";
import { Composition } from "remotion";
import { LONG_CHAPTERS, VIDEOS } from "./videos.generated";
import { WithCaptions } from "./engine/WithCaptions";
import { WithLongOverlay } from "./engine/WithLongOverlay";

// One composition per videos/<id>/ folder (registry generated by `npm run gen`), id "oj-<id>", 1080x1920 at 30 fps.
// Every video is wrapped in the one-word captions (`{"captions": false}` input prop turns them off).
const ENTRIES = VIDEOS.map((v) => {
  const Video = v.Component;
  const Wrapped: React.FC = () => (
    <WithCaptions words={v.words}>
      <Video />
    </WithCaptions>
  );
  return { id: v.id, frames: v.frames, Wrapped };
});

// One composition per long/<NNN-slug>/ch<N>/ chapter, id "ojl-<NNN-slug>-ch<N>", 1920x1080 at 30 fps, wrapped in the
// phrase subtitles and the chapter title card.
const LONG_ENTRIES = LONG_CHAPTERS.map((c) => {
  const Chapter = c.Component;
  const chapter = { n: c.n, title: c.title };
  const Wrapped: React.FC = () => (
    <WithLongOverlay words={c.words} chapter={chapter}>
      <Chapter />
    </WithLongOverlay>
  );
  return { id: c.id, frames: c.frames, Wrapped };
});

export const RemotionRoot: React.FC = () => (
  <>
    {ENTRIES.map((e) => (
      <Composition key={e.id} id={"oj-" + e.id} component={e.Wrapped} durationInFrames={e.frames} fps={30} width={1080} height={1920} />
    ))}
    {LONG_ENTRIES.map((e) => (
      <Composition key={"ojl-" + e.id} id={"ojl-" + e.id} component={e.Wrapped} durationInFrames={e.frames} fps={30} width={1920} height={1080} />
    ))}
  </>
);
